const now = new Date();
const timeZone = 'America/New_York';
const list = new Intl.DateTimeFormat('en-US', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hourCycle: 'h23',
  timeZoneName: 'shortOffset',
}).formatToParts(now);
const p = Object.fromEntries(list.map((part) => [part.type, part.value]));
const hour = Number(p.hour);
let editionId = 'evening';
let editionTitle = 'Evening Edition';
let slotHour = '20';
let timeLabel = '8:00 PM ET';
if (hour < 12) {
  editionId = 'morning';
  editionTitle = 'Morning Edition';
  slotHour = '08';
  timeLabel = '8:00 AM ET';
} else if (hour < 18) {
  editionId = 'afternoon';
  editionTitle = 'Afternoon Edition';
  slotHour = '14';
  timeLabel = '2:00 PM ET';
}
const hh = String(hour).padStart(2, '0');
const mm = String(p.minute).padStart(2, '0');
const ss = String(p.second).padStart(2, '0');
const date = p.year + '-' + p.month + '-' + p.day;
const offsetMatch = String(p.timeZoneName || '').match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
let offset = '-05:00';
if (offsetMatch) {
  offset = offsetMatch[1] + String(offsetMatch[2]).padStart(2, '0') + ':' + (offsetMatch[3] || '00');
}
const feeds = [
  { outlet: 'IGN', url: 'https://www.ign.com/rss/v2/articles/feed' },
  { outlet: 'GameSpot', url: 'https://www.gamespot.com/feeds/mashup/' },
  { outlet: 'Polygon', url: 'https://www.polygon.com/rss/index.xml' },
  { outlet: 'PC Gamer', url: 'https://www.pcgamer.com/rss/' },
  { outlet: 'Eurogamer', url: 'https://www.eurogamer.net/feed' },
];
return [{
  json: {
    date,
    editionId,
    editionTitle,
    timeLabel,
    publishedAt: date + 'T' + slotHour + ':00:00' + offset,
    updated: date + 'T' + hh + ':' + mm + ':' + ss + offset,
    filePath: 'content/reports/' + date + '.md',
    feeds,
  },
}];

const edition = $('Resolve edition').first().json;
const inputItems = $input.all().map((item) => item.json);
let rows = inputItems;
if (inputItems.length === 1 && Array.isArray(inputItems[0].data)) rows = inputItems[0].data;

function strip(html) {
  return String(html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function outletFromLink(link) {
  try {
    const host = new URL(link).hostname.replace(/^www\./, '');
    if (host.includes('ign.com')) return 'IGN';
    if (host.includes('gamespot.com')) return 'GameSpot';
    if (host.includes('polygon.com')) return 'Polygon';
    if (host.includes('pcgamer.com')) return 'PC Gamer';
    if (host.includes('eurogamer.net')) return 'Eurogamer';
    return host;
  } catch {
    return 'Unknown';
  }
}

const seen = new Set();
const stories = [];
for (const row of rows) {
  if (!row || row.error) continue;
  const link = row.link || row.url || '';
  const title = strip(row.title);
  if (!title || !link || seen.has(link)) continue;
  seen.add(link);
  stories.push({
    outlet: outletFromLink(link),
    title,
    link,
    summary: strip(row.contentSnippet || row.content || row.description || '').slice(0, 320),
  });
  if (stories.length >= 24) break;
}

if (stories.length === 0) {
  throw new Error('No gaming RSS items were fetched. Refusing to write an edition without sources.');
}

const catalog = stories
  .map((story, index) => (index + 1) + '. [' + story.outlet + '] ' + story.title + '\n   ' + story.link + '\n   ' + story.summary)
  .join('\n');

const prompt = [
  'Write the ' + edition.editionTitle + ' of Gaming Pulse for ' + edition.date + '.',
  'Use only the sources below. Do not invent quotes, prices, dates, or numbers.',
  'Skip items that are not about video games.',
  'Pick 3 to 5 stories. Each story is a level-3 markdown heading, one or two short paragraphs that name the outlet, and a markdown link.',
  'Do not include a level-2 heading, a time label, an HTML anchor, or YAML frontmatter. The workflow adds those.',
  'Return a JSON object with these keys:',
  '- description: one line, 160 characters or fewer, no line break',
  '- summary: one sentence lead for this edition',
  '- tags: array of 2 to 6 lowercase tags, spaces written as hyphens',
  '- markdown: the stories only',
  '',
  'Sources:',
  catalog,
].join('\n');

return [{ json: { prompt, storyCount: stories.length } }];

const edition = $('Resolve edition').first().json;
const llm = $('Write edition').first().json;
const file = $input.first().json;

function unquote(value) {
  let v = String(value ?? '').trim();
  if (
    (v.startsWith('"') && v.endsWith('"') && v.length >= 2) ||
    (v.startsWith("'") && v.endsWith("'") && v.length >= 2)
  ) {
    v = v.slice(1, -1);
  }
  return v.replace(/\\n/g, ' ').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
}

function yamlQuote(value) {
  const s = String(value).replace(/\r?\n/g, ' ').trim();
  return '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}

function normalizeTag(tag) {
  return String(tag)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

function splitFrontmatter(markdown) {
  const match = String(markdown).match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!match) return null;
  return { frontmatter: match[1], body: match[2] };
}

function parseFrontmatter(frontmatter) {
  const doc = { scalars: {}, tags: [], editions: [] };
  let mode = null;
  let current = null;
  for (const line of frontmatter.split(/\r?\n/)) {
    if (!line.trim()) continue;
    if (mode === 'editions' && line.startsWith('  - ')) {
      if (current) doc.editions.push(current);
      current = {};
      const rest = line.slice(4);
      const idx = rest.indexOf(':');
      if (idx !== -1) current[rest.slice(0, idx).trim()] = unquote(rest.slice(idx + 1));
      continue;
    }
    if (mode === 'editions' && line.startsWith('    ') && current) {
      const rest = line.trim();
      const idx = rest.indexOf(':');
      if (idx !== -1) current[rest.slice(0, idx).trim()] = unquote(rest.slice(idx + 1));
      continue;
    }
    if (mode === 'tags' && line.startsWith('  - ')) {
      doc.tags.push(unquote(line.slice(4)));
      continue;
    }
    if (/^[A-Za-z0-9_-]+:/.test(line)) {
      if (current) {
        doc.editions.push(current);
        current = null;
      }
      const idx = line.indexOf(':');
      const key = line.slice(0, idx).trim();
      const value = line.slice(idx + 1).trim();
      if (key === 'tags' && value === '') {
        mode = 'tags';
        continue;
      }
      if (key === 'editions' && value === '') {
        mode = 'editions';
        continue;
      }
      mode = null;
      doc.scalars[key] = unquote(value);
    }
  }
  if (current) doc.editions.push(current);
  return doc;
}

function emitFrontmatter(doc) {
  const lines = [];
  lines.push(`title: ${yamlQuote(doc.scalars.title)}`);
  lines.push(`date: ${doc.scalars.date}`);
  lines.push(`description: ${yamlQuote(doc.scalars.description)}`);
  const tags = doc.tags.filter(Boolean);
  if (tags.length === 0) lines.push('tags: []');
  else {
    lines.push('tags:');
    for (const tag of tags) lines.push(`  - ${yamlQuote(tag)}`);
  }
  if (doc.scalars.cover) lines.push(`cover: ${yamlQuote(doc.scalars.cover)}`);
  lines.push(`updated: ${doc.scalars.updated}`);
  lines.push(`sample: ${doc.scalars.sample === true || doc.scalars.sample === 'true' ? 'true' : 'false'}`);
  const known = new Set(['title', 'date', 'description', 'tags', 'cover', 'updated', 'sample', 'editions']);
  for (const key of Object.keys(doc.scalars)) {
    if (!known.has(key) && doc.scalars[key] !== '') lines.push(`${key}: ${yamlQuote(doc.scalars[key])}`);
  }
  lines.push('editions:');
  for (const ed of doc.editions) {
    lines.push(`  - id: ${ed.id}`);
    lines.push(`    title: ${yamlQuote(ed.title)}`);
    lines.push(`    publishedAt: ${ed.publishedAt}`);
    if (ed.summary) lines.push(`    summary: ${yamlQuote(ed.summary)}`);
    for (const key of Object.keys(ed)) {
      if (!['id', 'title', 'publishedAt', 'summary'].includes(key) && ed[key] !== '') {
        lines.push(`    ${key}: ${yamlQuote(ed[key])}`);
      }
    }
  }
  return lines.join('\n');
}

function extractPayload(llm) {
  let content = llm?.message?.content ?? llm?.content ?? llm?.text ?? llm;
  if (content && typeof content === 'object' && content.content && !content.markdown) {
    content = content.content;
  }
  if (typeof content === 'string') {
    const trimmed = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
    content = JSON.parse(trimmed);
  }
  if (!content || typeof content !== 'object' || Array.isArray(content)) {
    throw new Error('LLM output was not a JSON object with description, summary, tags, and markdown.');
  }
  return content;
}

function decodeContent(content) {
  const raw = String(content);
  if (raw.trimStart().startsWith('---')) return raw;
  const compact = raw.replace(/\n/g, '');
  const decoded = Buffer.from(compact, 'base64').toString('utf8');
  return decoded;
}

function isMissing(file) {
  if (!file || typeof file !== 'object') return true;
  if (file.sha && file.content) return false;
  const msg =
    typeof file.error === 'string'
      ? file.error
      : file.error && typeof file.error.message === 'string'
        ? file.error.message
        : JSON.stringify(file.error || file.message || '');
  if (/404|not found/i.test(msg)) return true;
  if (!file.content) {
    throw new Error(`Could not read today's report (${msg || 'unknown error'}). Refusing to create a duplicate.`);
  }
  return false;
}

function upsertSection(body, editionId, section) {
  const re = new RegExp(`<span id="${editionId}"><\\/span>[\\s\\S]*?(?=<span id="[a-z0-9-]+"><\\/span>|$)`);
  const block = section.replace(/\s*$/, '\n');
  if (re.test(body)) return body.replace(re, block);
  const trimmed = String(body || '').replace(/\s*$/, '');
  if (!trimmed) return `\n${block}`;
  return `${trimmed}\n\n${block}`;
}

const payload = extractPayload(llm);
const story = String(payload.markdown || '')
  .replace(/^---[\s\S]*?\n---\s*/, '')
  .replace(new RegExp(`^<span id="${edition.editionId}"><\\/span>\\s*`, 'i'), '')
  .replace(new RegExp(`^##\\s+${edition.editionTitle}\\s*`, 'i'), '')
  .replace(/^_[^_\n]+_\s*/, '')
  .trim();
if (!story) throw new Error('LLM returned an empty edition.');

const description = String(payload.description || payload.summary || '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 180);
const summary = String(payload.summary || description).replace(/\s+/g, ' ').trim().slice(0, 240);
if (!description) throw new Error('LLM returned no description.');

const incomingTags = Array.isArray(payload.tags)
  ? payload.tags
  : typeof payload.tags === 'string'
    ? payload.tags.split(',')
    : [];

const [year, month, day] = String(edition.date).split('-').map(Number);
const longDate = new Intl.DateTimeFormat('en-US', {
  timeZone: 'UTC',
  month: 'long',
  day: 'numeric',
  year: 'numeric',
}).format(new Date(Date.UTC(year, month - 1, day)));

const section = [
  `<span id="${edition.editionId}"></span>`,
  '',
  `## ${edition.editionTitle}`,
  '',
  `_${edition.timeLabel}_`,
  '',
  story,
  '',
].join('\n');

const order = { morning: 0, afternoon: 1, evening: 2 };
let doc;
let body;
const exists = !isMissing(file);

if (!exists) {
  doc = {
    scalars: {
      title: `Gaming Pulse — ${longDate}`,
      date: edition.date,
      description,
      updated: edition.updated,
      sample: 'false',
    },
    tags: [],
    editions: [],
  };
  body = '';
} else {
  const decoded = decodeContent(file.content);
  const parsed = splitFrontmatter(decoded);
  if (!parsed) throw new Error('Existing report has no frontmatter. Refusing to overwrite it.');
  doc = parseFrontmatter(parsed.frontmatter);
  doc.scalars.date = edition.date || doc.scalars.date;
  doc.scalars.updated = edition.updated;
  doc.scalars.description = description;
  if (!doc.scalars.title) doc.scalars.title = `Gaming Pulse — ${longDate}`;
  body = parsed.body;
}

const merged = [];
for (const tag of [...doc.tags, ...incomingTags]) {
  const clean = normalizeTag(tag);
  if (clean && !merged.includes(clean)) merged.push(clean);
}
doc.tags = merged.slice(0, 12);

const nextEdition = {
  id: edition.editionId,
  title: edition.editionTitle,
  publishedAt: edition.publishedAt,
  summary,
};
const without = doc.editions.filter((item) => item.id !== edition.editionId);
without.push(nextEdition);
without.sort((a, b) => (order[a.id] ?? 9) - (order[b.id] ?? 9) || String(a.id).localeCompare(String(b.id)));
doc.editions = without;

body = upsertSection(body, edition.editionId, section);
const fileContent = `---\n${emitFrontmatter(doc)}\n---\n${body.replace(/^\n?/, '\n')}`.replace(/\n{3,}/g, '\n\n').replace(/\s*$/, '\n');

const verb = exists ? 'Update' : 'Add';
return [
  {
    json: {
      exists,
      filePath: edition.filePath,
      fileContent,
      commitMessage: `${verb} ${edition.editionId} edition for ${edition.date}`,
    },
  },
];
